'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const T = nextInt();

const types = new Int32Array(N);
for (let i = 0; i < N; i++) types[i] = nextInt();

const items = new Array(N);
for (let i = 0; i < N; i++) {
  items[i] = { t: types[i], p: nextInt() };
}

items.sort((a, b) => a.t - b.t || a.p - b.p);

const itemType = new Int32Array(N);
const itemPrice = new Int32Array(N);
const ptr = new Int32Array(T + 1);
const end = new Int32Array(T + 1);

for (let i = 0; i < N; i++) {
  const item = items[i];
  itemType[i] = item.t;
  itemPrice[i] = item.p;
  if (i === 0 || items[i - 1].t !== item.t) ptr[item.t] = i;
  end[item.t] = i + 1;
}

const heap = [];

function less(a, b) {
  return itemPrice[a] < itemPrice[b] ||
    (itemPrice[a] === itemPrice[b] && itemType[a] < itemType[b]);
}

function heapPush(value) {
  let i = heap.length;
  heap.push(value);
  while (i > 0) {
    const parent = (i - 1) >> 1;
    if (!less(value, heap[parent])) break;
    heap[i] = heap[parent];
    i = parent;
  }
  heap[i] = value;
}

function heapPop() {
  const root = heap[0];
  const last = heap.pop();
  if (heap.length > 0) {
    let i = 0;
    while (true) {
      const left = i * 2 + 1;
      if (left >= heap.length) break;
      const right = left + 1;
      let child = left;
      if (right < heap.length && less(heap[right], heap[left])) child = right;
      if (!less(heap[child], last)) break;
      heap[i] = heap[child];
      i = child;
    }
    heap[i] = last;
  }
  return root;
}

for (let t = 1; t <= T; t++) {
  if (ptr[t] < end[t]) heapPush(ptr[t]);
}

const C = nextInt();
let total = 0;

for (let j = 0; j < C; j++) {
  const u = nextInt();

  if (u === 0) {
    while (heap.length > 0) {
      const index = heap[0];
      if (ptr[itemType[index]] === index) break;
      heapPop();
    }
    if (heap.length === 0) continue;

    const index = heapPop();
    const t = itemType[index];
    total += itemPrice[index];
    ptr[t]++;
    if (ptr[t] < end[t]) heapPush(ptr[t]);
  } else if (ptr[u] < end[u]) {
    const index = ptr[u];
    total += itemPrice[index];
    ptr[u]++;
    if (ptr[u] < end[u]) heapPush(ptr[u]);
  }
}

